  /** A person's settled-total: the due figures of their settled claims that count (their frozen
   *  figures, corrections included), skipping those with no due. */
  protected settledTotalOf(p: Person): string {
    return this.statusTotalOf(p, (c) => c.status === 'SETTLED');
  }

  /** A person's score: their settled-total divided by 100, minus 5 for each of their overdue
   *  claims that count, rounded half to even to a whole number. Worked in whole cents. */
  protected scoreOf(p: Person): string {
    const cents = Math.round(Number(this.settledTotalOf(p)) * 100) - 50000 * this.overdueOf(p).length;
    const whole = Math.floor(cents / 10000);
    const rest = cents - whole * 10000;
    const score = rest > 5000 || (rest === 5000 && whole % 2 !== 0) ? whole + 1 : whole;
    return String(score);
  }

  /** A person's band by their score while both score thresholds are set: HIGH at or above the high
   *  one, MID at or above the mid one, else LOW; empty while either is blank. */
  protected bandOf(p: Person): string {
    const mid = this.scoreMid();
    const high = this.scoreHigh();
    if (mid === null || high === null) return '';
    const score = Number(this.scoreOf(p));
    return score >= high ? 'HIGH' : score >= mid ? 'MID' : 'LOW';
  }

